#!/usr/bin/env node
/**
 * Generates the theme-completeness list (issue #3826).
 *
 * Required theme tokens = every `--smrt-*` name referenced via `var(...)` in a
 * `.svelte` file under `packages/*\/src`, minus component-private names. A name
 * is component-private only when every package that consumes it also defines it
 * itself (`--smrt-<component>-*` in its own CSS or script), so the consuming
 * package never depends on a theme for it. Override hooks
 * (`OVERRIDE_HOOKS`) are listed as optional, not required.
 *
 * Outputs (both checked in, both regenerated by this script):
 *   - packages/smrt-ui/src/themes/required-tokens.generated.json
 *       read by `src/themes/__tests__/required-tokens.test.ts`
 *   - the block between the `smrt-required-tokens` markers in
 *       packages/smrt-ui/src/themes/CUSTOM_THEME_GUIDE.md
 *
 * Usage:
 *   node scripts/generate-smrt-required-tokens.mjs          # rewrite outputs
 *   node scripts/generate-smrt-required-tokens.mjs --check  # exit 1 if stale
 */

import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import {
  collectConsumedByPackage,
  collectDefinedInCss,
  collectInlineByPackage,
  listFiles,
  OVERRIDE_HOOKS,
  ROOT,
} from './smrt-token-scan-lib.mjs';

export const JSON_PATH = join(
  ROOT,
  'packages/smrt-ui/src/themes/required-tokens.generated.json',
);
export const GUIDE_PATH = join(ROOT, 'packages/smrt-ui/src/themes/CUSTOM_THEME_GUIDE.md');
const START = '<!-- smrt-required-tokens:start -->';
const END = '<!-- smrt-required-tokens:end -->';

/** Compute the required and optional token sets. */
export function computeTokenSets() {
  const { byPackage } = collectConsumedByPackage({ exts: ['.svelte'] });
  const inlineByPkg = collectInlineByPackage();
  const themeDefined = new Set();
  for (const file of listFiles(join(ROOT, 'packages/smrt-ui/src/themes/styles'), ['.css'])) {
    collectDefinedInCss(readFileSync(file, 'utf8'), themeDefined);
  }
  const required = new Set();
  const optional = new Set();
  for (const [token, consumers] of byPackage) {
    if (OVERRIDE_HOOKS.has(token)) {
      optional.add(token);
      continue;
    }
    // Private to the consuming set only when every consumer defines it itself.
    const allPrivate = [...consumers].every((pkg) => inlineByPkg.get(pkg)?.has(token));
    if (themeDefined.has(token) || !allPrivate) required.add(token);
  }
  return { required: [...required].sort(), optional: [...optional].sort() };
}

/** Markdown block for CUSTOM_THEME_GUIDE.md, grouped by family. */
export function renderGuideSection({ required }) {
  const families = new Map();
  for (const token of required) {
    const family = token.replace(/^--smrt-/, '').split('-')[0];
    if (!families.has(family)) families.set(family, []);
    families.get(family).push(token);
  }
  const lines = [
    START,
    '',
    '### Required tokens (generated)',
    '',
    'Every theme (presets and `createTheme()` output) must define these names. Generated by',
    '`scripts/generate-smrt-required-tokens.mjs`; do not edit by hand. Component-private',
    '`--smrt-<component>-*` knobs are excluded.',
    '',
  ];
  for (const [family, tokens] of [...families].sort(([a], [b]) => a.localeCompare(b))) {
    lines.push(`- **${family}** (${tokens.length}): ${tokens.map((t) => `\`${t}\``).join(', ')}`);
  }
  lines.push('', END);
  return lines.join('\n');
}

/** Replace the marked block inside the guide text. */
export function spliceGuide(text, section) {
  const s = text.indexOf(START);
  const e = text.indexOf(END);
  if (s === -1 || e === -1 || e < s) {
    throw new Error(`CUSTOM_THEME_GUIDE.md is missing the ${START} / ${END} markers`);
  }
  return text.slice(0, s) + section + text.slice(e + END.length);
}

function renderJson({ required, optional }) {
  return (
    JSON.stringify(
      {
        $comment:
          'Generated by scripts/generate-smrt-required-tokens.mjs. Do not edit by hand.',
        required,
        optional,
      },
      null,
      2,
    ) + '\n'
  );
}

function main() {
  const check = process.argv.includes('--check');
  const sets = computeTokenSets();
  const json = renderJson(sets);
  const guideText = readFileSync(GUIDE_PATH, 'utf8');
  const guide = spliceGuide(guideText, renderGuideSection(sets));

  const jsonOnDisk = existsSync(JSON_PATH) ? readFileSync(JSON_PATH, 'utf8') : '';
  const stale = [];
  if (jsonOnDisk !== json) stale.push(JSON_PATH);
  if (guideText !== guide) stale.push(GUIDE_PATH);

  if (check) {
    if (stale.length > 0) {
      console.error(
        `required-tokens list is stale: ${stale.map((p) => p.replace(ROOT + '/', '')).join(', ')}\n` +
          'Run `node scripts/generate-smrt-required-tokens.mjs` and commit the result.',
      );
      process.exit(1);
    }
    console.log(
      `required-tokens: ${sets.required.length} required, ${sets.optional.length} optional, up to date.`,
    );
    process.exit(0);
  }

  writeFileSync(JSON_PATH, json);
  writeFileSync(GUIDE_PATH, guide);
  console.log(
    `required-tokens: wrote ${sets.required.length} required, ${sets.optional.length} optional.`,
  );
}

if (import.meta.url === `file://${process.argv[1]}`) main();
